#include <stdio.h>
int main(void) {
    int n = 3;
    int values[3] = {3, -1, 2};
    int sum = 0;
    for (int i = 0; (i < n); i = (i + 1)) {
        sum = (sum + values[i]);
    }
    printf("%d\n", sum);
    return 0;
}

